const exp = JSON.parse(readFileSync(process.cwd() + "/tests/expected.json", "utf8"));
let prev = exp.input;
for (let i = 1; i <= 48; i++) {
  const mod = await import(process.cwd() + "/src/s" + String(i).padStart(2,"0") + ".js");
  const want = exp.stages[i-1];
  let got, err = null;
  try { got = mod["step"+i](prev); } catch (e) { err = e.constructor.name + ": " + e.message; }
  if (err || got !== want) {
    console.log(`s${String(i).padStart(2,"0")} step${i}: in=${prev} want=${want} ` + (err ? `THROW ${err}` : `got=${got}`));
  }
  prev = want;
}
console.log("--- done ---");
EOF
