import { readFileSync } from "node:fs";
const exp = JSON.parse(readFileSync(process.cwd() + "/tests/expected.json", "utf8"));
const S = (i) => exp.stages[i-1];

// Type A: (v + floor(v/3) + c) % 997  -> find c
console.log("== type A: (v + floor(v/3) + c) % 997 ==");
for (let i = 1; i <= 48; i++) {
  const v = i === 1 ? exp.input : S(i-1);
  const base = v + Math.floor(v/3);
  const want = S(i);
  // candidate c in 0..996
  const c = (want - base % 997 + 997 * 2) % 997;
  console.log(`i=${String(i).padStart(2)} base=${base} want=${want} c=${c}`);
}
EOF
