cat > /tmp/analyze3.mjs <<'EOF'
const S = (i,st) => st[i-1];
const st = [9,7,18,37,49,27,74,149,198,192,565,131,174,140,405,811,84,106,299,599,798,772,311,623,830,776,319,639,852,838,501,3,4,42,91,183,244,254,723,447,596,626,844,689,918,916,719,439];
const ks = [14,42,6,34,62,26,54,18,46,10,38,2];
const is = [2,6,10,14,18,22,26,30,34,38,42,46];

// candidate formulas for k(i)
const cands = {
  "(i*3+8)%64": (i)=>(i*3+8)%64,
  "((i+1)*7)%64": (i)=>((i+1)*7)%64,
  "(i*7)%64":  (i)=>(i*7)%64,
  "(i*3)%64+8": (i)=>(i*3)%64+8,
  "((i+1)*7)%64+?" : null,
};
console.log("target k by i:", is.map((i,j)=>`${i}:${ks[j]}`).join(" "));
for (const [name,f] of Object.entries(cands)) {
  if (!f) continue;
  const got = is.map(f);
  const ok = got.every((g,j)=>g===ks[j]);
  console.log(`${ok?"MATCH ":"no    "} ${name.padEnd(18)} -> ${got.join(",")}`);
}
// search: k = (a*i + b) % 64
console.log("\nbrute force k=(a*i+b)%64:");
for (let a=0;a<64;a++) for (let b=0;b<64;b++) {
  if (is.every((i,j)=>((a*i+b)%64)===ks[j])) console.log("  FOUND a="+a+" b="+b);
}
// search: k=(a*(i+c)+b)%64  generalized
console.log("brute force k=(a*i+b)%m for m in {32,64,128}:");
for (const m of [16,32,64,100,128]) for (let a=0;a<m;a++) for (let b=0;b<m;b++) {
  if (is.every((i,j)=>((a*i+b)%m)===ks[j])) console.log(`  FOUND m=${m} a=${a} b=${b}`);
}
EOF
