cat > /tmp/sim.mjs <<'EOF'
import { readFileSync } from "node:fs";
const exp = JSON.parse(readFileSync(process.cwd() + "/tests/expected.json", "utf8"));
const stage = (i, v) => {
  if (i % 4 === 1) return (v + Math.floor(v / 3)) % 997;        // A
  if (i % 4 === 2) return v ^ ((i * 7) % 64);                    // B
  if (i % 4 === 3) return (v * 3 - i) % 991;                     // C
  return (v * 2 + 1) % 1000;                                      // D
};
let v = exp.input, bad = 0;
for (let i = 1; i <= 48; i++) {
  v = stage(i, v);
  if (v !== exp.stages[i-1]) { console.log(`FAIL i=${i} got=${v} want=${exp.stages[i-1]}`); bad++; }
}
console.log(bad === 0 ? "SIMULATION: 48/48 GREEN" : `SIMULATION: ${bad} mismatches`);
EOF
node /tmp/sim.mjs

